\section{Reproducibility and Prospective
Interface}\label{6-reproducibility-and-prospective-interface}}

\begin{enumerate}
\def\labelenumi{\arabic{enumi}.}
\tightlist
\item
  perform a separately authorized source-finalization pass for exact
  theorem passages, hypotheses, correction state, and any required
  retraction/source-conflict checks;
\item
  bind \texttt{SG2OwnerCanonical-v1} to the exact marked presentation
  with an independent verifier and prefix-completeness theorem;
\item
  derive the higher-content and zero-content owner factors from the deck
  action, including primitive-lift status and both fixed normalizations;
\item
  construct the positive-content and zero-content formal objects
  separately and prove singleton projection validity;
\item
  execute one target-blind higher-content and one zero-content
  comparison only under new scientific authorization;
\item
  stop the universal program upon a certified adverse result, or
  document survival without promoting it to recovery; and
\item
  only after survival, formulate and prove the content-one
  compact-uniform tail theorem on every frozen schedule and limit order.
\end{enumerate}
